// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddress) public {
        // Deploy a minimal oracle-like contract so that c's initialize can set a valid oracle.
        // We use an arbitrary contract with code, because UPayoffProvider.__UPayoffProvider__initialize
        // calls Address.isContract on the oracle argument.
        OracleStub stub = new OracleStub();

        // The initializer can only be called once. We don't know the exact ProductInfo
        // for C's initialize, but the fuzzer supplies oracleAddress, which determines
        // the actual address stored. To satisfy the property for all inputs, we must
        // be able to call oracle() after initialization. Since C was deployed without
        // initialization, we cannot directly test oracle() because it will be zero.
        // However, the property is that oracle() returns the stored oracle.
        // In the reference, it returns the oracle set during initialization.
        // In the bug, it always returns address(0).
        // We can test this by checking that the return value equals the address
        // we would expect to be stored. Because initialize is protected by initializer(1)
        // and requires the caller to be IController(msg.sender), which is Test contract,
        // we can initialize c with the oracle address we want.

        // Prepare ProductInfo
        C.ProductInfo memory info;
        info.oracle = IOracleProvider(address(stub));
        info.payoffDefinition = PayoffDefinitionLib.PayoffType(0); // simple transform, not important
        // We need a valid payoff definition. Since we can't easily construct arbitrary ones,
        // we use a known simple one: PassThrough with no data? The library checks validity.
        // To avoid complexity, we use a payoff that is always valid: a constant pass-through.
        // We can fuzz oracleAddress instead of the stub. But the initialize function
        // takes info.oracle, so we set info.oracle = IOracleProvider(oracleAddress).
        // However, oracleAddress is fuzzed and might not have code, causing revert.
        // So we need to assume it has code. vm.assume(oracleAddress.code.length > 0);

        vm.assume(oracleAddress.code.length > 0);
        info.oracle = IOracleProvider(oracleAddress);

        // The rest of ProductInfo must be set. We can set dummy values that don't revert.
        // Since we just want to test oracle(), we don't care if later operations revert.
        info.name = "test";
        info.symbol = "TEST";
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(1e17);
        info.makerFee = UFixed18.wrap(1e17);
        info.takerFee = UFixed18.wrap(1e17);
        info.positionFee = UFixed18.wrap(1e17);
        info.makerLimit = UFixed18.wrap(1000e18);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(1e17)),
            maxRate: PackedFixed18.wrap(int128(5e17)),
            targetRate: PackedFixed18.wrap(int128(2e17)),
            targetUtilization: PackedUFixed18.wrap(uint128(0.8e18))
        });

        // The initializer expects the caller to be IController. We are not a controller,
        // but the `initialize` function first calls __UControllerProvider__initialize which stores
        // msg.sender as controller. Since we are the Test contract, we become the controller.
        // That's fine; we just need to fulfill the requirement that controller().isProduct(C) returns true.
        // However, our Test contract does not implement IController, so further calls might revert,
        // but for the purpose of checking oracle() after initialization, it's fine.

        // Initialize the contract
        vm.prank(address(this));
        c.initialize(info);

        // Now the property: oracle() must return the stored oracle address.
        assertEq(address(c.oracle()), oracleAddress);
    }
}

// Minimal stub just to have code; C's oracle() will return the address.
// The fuzzer provides oracleAddress with code, so we don't necessarily need this stub,
// but we keep it as a convenience for the vm.assume check.
contract OracleStub {
    fallback() external payable { revert(); }
}

