        // Deploy a minimal oracle helper to satisfy isContract check during initialize
        OracleStub stub = new OracleStub();
        address stubAddr = address(stub);

        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(stubAddr);
        info.payoffDefinition = PayoffDefinition(PayoffDefinitionLib.PayoffType(0), PayoffDefinitionLib.PayoffDirection(0), bytes30(0));
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(1e17);
