        info.takerFee = UFixed18.wrap(1e17);
        info.positionFee = UFixed18.wrap(1e17);
        info.makerLimit = UFixed18.wrap(1000e18);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(0)
        );
        c.initialize(info);

        // The stored oracle should be the stub address, not address(0)
        assertTrue(address(c.oracle()) == stubAddr);
    }
}

