pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();

        // Build a ProductInfo with a non-zero oracle address
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(address(0x1234)); // non-zero address

        // Initialize the contract (must be called by controller/deployer)
        // The contract expects msg.sender to be the controller
        // We prank as address(this) because initialize expects IController(msg.sender)
        // But C is not actually deployed through Controller, so we mock by pretending
        // The initializer modifier allows msg.sender == controller() check;
        // since controller() will return address(0) (unset), we can prank to pass the check
        // However, __UControllerProvider__initialize stores msg.sender as controller
        vm.startPrank(address(this));
        c.initialize(info);
        vm.stopPrank();
    }

    function testFuzz_property(address fuzzedOracle) public {
        // bound to non-zero to avoid trivial pass on zero
        vm.assume(fuzzedOracle != address(0));

        // Deploy a fresh C for each run with the fuzzed oracle
        C freshC = new C();
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(fuzzedOracle);

        vm.prank(address(this));
        freshC.initialize(info);

        // The property: oracle() must return the address we set
        address returnedOracle = address(freshC.oracle());
        assertTrue(returnedOracle == fuzzedOracle, "oracle() does not return the initialized address");
    }
}

