pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // Deploy C; it is uninitialized, but we only test oracle()
        c = new C();
    }

    function testFuzz_property(uint256 param) public {
        // vm.assume(param > 0); // keep domain wide, just example

        // Call oracle() on uninitialized C — it returns the stored address.
        // _oracle storage is uninitialized, so it returns address(0).
        // The reference returns address(0) which is not a contract, but it returns it anyway.
        // The mutant returns address(0x...01) which is also not a contract.
        // The difference: both are non-contract addresses, but we need to observe a behavioral difference.
        // The oracle() return value is used in currentVersion() which calls oracle().currentVersion().
        // Both will revert because address(0) and address(0x...01) have no code.
        // However, the bug is about the returned address itself being different.
        // We can observe it directly: the getter returns a value.
        // Rule: oracle() never returns address(0x...01).
        // But that's a constant assertion, not allowed.
        // We need a behavioral property. We can deploy a fake oracle contract and store it via initialization? No, C is uninitialized.
        // We can initialize C using the controller, but that requires complex setup.
        // Simplest: oracle() getter doesn't revert, and the returned value is not the hardcoded wrong address.
        // However, we cannot assert on a constant.
        // We need an external call that succeeds on reference but fails on mutant or vice versa.
        // We'll deploy a mock oracle that always returns successfully, and initialize C with it via controller.
        // But we can't import C to call initialize. We must use the public interface IProduct.
        // C is IProduct. We can create a mock controller, mock oracle, and initialize C.
        // That's allowed to set up the scenario.
        // We'll deploy a MockController that allows initialization, and a MockOracle that is a contract.
        // Then oracle() on reference returns the MockOracle address; on mutant returns 0x...01.
        // We then call c.currentVersion() — it calls oracle().currentVersion().
        // On reference, MockOracle.currentVersion() succeeds; on mutant, it calls 0x...01.currentVersion() which is an EOA with no code -> low-level call succeeds but returns empty bytes, which may cause revert in decoding.
        // Actually, calling an EOA with any calldata returns (true, empty bytes). The IOracleProvider.currentVersion() expects a struct return, so it will revert on decoding empty bytes.
        // So we can assert that c.currentVersion() does not revert on reference.
        // We'll fuzz param to make it non-trivial.

        // Deploy mock oracle
        MockOracle mo = new MockOracle();
        // Deploy mock controller
        MockController mc = new MockController();

        // Prepare product info
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "T",
            payoffDefinition: PayoffDefinition(PayoffDefinitionLib.PayoffType.PASS_THROUGH, PayoffDefinitionLib.PayoffDirection.LONG, bytes30(0)),
            oracle: IOracleProvider(address(mo)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(type(uint128).max)
            })
        });

        // Initialize C via controller
        vm.prank(address(mc));
        c.initialize(info);

        // Now oracle() returns mo on reference, 0x...01 on mutant.
        // Call currentVersion() — it will call oracle().currentVersion().
        // On reference, mo.currentVersion() returns a valid struct; on mutant, 0x...01.currentVersion() low-level call succeeds but returns empty bytes, causing revert in decoding.
        bool success;
        try c.currentVersion() returns (IOracleProvider.OracleVersion memory) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success);
    }
}

contract MockOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
}

contract MockController {
    function isProduct(IProduct) external pure returns (bool) { return true; }
    function owner() external view returns (address) { return address(this); }
    function owner(uint256) external view returns (address) { return address(this); }
    function owner(IProduct) external view returns (address) { return address(this); }
    function coordinatorFor(IProduct) external pure returns (uint256) { return 1; }
    function collateral() external view returns (ICollateral) { return ICollateral(address(0)); }
    function incentivizer() external view returns (IIncentivizer) { return IIncentivizer(address(0)); }
    function minFundingFee() external pure returns (UFixed18) { return UFixed18.wrap(0); }
    function paused() external pure returns (bool) { return false; }
    function multiInvoker() external pure returns (IMultiInvoker) { return IMultiInvoker(address(0)); }
    function productBeacon() external pure returns (IBeacon) { return IBeacon(address(0)); }
    function programsPerProduct() external pure returns (uint256) { return 0; }
}

