pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddress, bytes30 payoffData) public {
        vm.assume(oracleAddress != address(0));
        // Keep the oracle address in the admissible domain (any non-zero address)
        vm.assume(oracleAddress != address(0x0000000000000000000000000000000000000001));

        // Create a minimal contract at the oracle address so that initialize doesn't revert due to non-contract
        vm.etch(oracleAddress, hex"00");

        C.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TEST";
        info.oracle = IOracleProvider(oracleAddress);
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
            data: payoffData
        });
        info.maintenance = UFixed18.wrap(0.01e18);
        info.fundingFee = UFixed18.wrap(0.001e18);
        info.makerFee = UFixed18.wrap(0.001e18);
        info.takerFee = UFixed18.wrap(0.001e18);
        info.positionFee = UFixed18.wrap(0.001e18);
        info.makerLimit = UFixed18.wrap(100e18);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: Fixed18.wrap(0.01e18),
            maxRate: Fixed18.wrap(1e18),
            targetRate: Fixed18.wrap(0.5e18),
            targetUtilization: UFixed18.wrap(0.8e18)
        });

        // Ensure payoffDefinition is valid
        vm.assume(info.payoffDefinition.valid());

        // Initialize C through its initializer entry point
        c.initialize(info);

        // Assert: the returned oracle address equals the one we passed in
        assertTrue(address(c.oracle()) == oracleAddress);
    }
}

