pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address oracle, bytes30 data) public {
        // Admissible domain: oracle must be a contract address (per _updateOracle checks)
        // Since fuzzed addresses are EOAs with empty code, we need to pre-deploy a minimal contract.
        vm.assume(oracle != address(0));
        // Deploy a minimal oracle contract that satisfies Address.isContract(oracle)
        OracleMock orc = new OracleMock();
        oracle = address(orc);

        // Build a PayoffDefinition from fuzzed data (payoffType and payoffDirection set to valid values)
        C.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(oracle);
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(0)
        );
        // PayoffDefinition: payoffType and payoffDirection are set from data bytes
        PayoffDefinition memory payoffDef;
        payoffDef.payoffType = PayoffDefinitionLib.PayoffType(PayoffDefinitionLib.PayoffType.PASSTHROUGH);
        payoffDef.payoffDirection = PayoffDefinitionLib.PayoffDirection(0);
        payoffDef.data = data;
        info.payoffDefinition = payoffDef;

        // Initialize the contract as if called by a controller (any address)
        // We need to bypass the onlyInitializer modifier; call initialize with initializer(1) modifier will work only once.
        // We deploy a minimal controller mock
        ControllerMock ctrl = new ControllerMock();
        // Make the controller return true for isProduct for address(c) so that modifiers pass after init
        // For simplicity, we set up the controller to return the product as valid.
        // Actually, UControllerProvider stores msg.sender as controller. So we need to init with a contract address.
        // We'll use this contract as controller for init?
        // The initializer takes IController(msg.sender). We need msg.sender to be IController.
        // So we must deploy c from a controller contract to pass the check. We'll use ControllerMock as the msg.sender.
        // Re-deploy c with ControllerMock calling new C() in its constructor? Too complex. Instead, we can exploit the fact that initializer checks isContract, so we can use this test contract as controller.
        // Better: deploy c directly and then use prank from a controller contract address.
        // Since we cannot easily have a constructor call from a contract, we'll deploy a setup helper.
        // For simplicity, we initialize inside a helper that ensures msg.sender is a contract.
        SetupHelper helper = new SetupHelper();
        (C product, ControllerMock controller) = helper.createProduct(oracle, data);
        c = product;

        // Now the invariant: payoffDefinition() must return the original definition without forced PASSTHROUGH.
        PayoffDefinition memory returnedDef = c.payoffDefinition();
        assertTrue(returnedDef.payoffType == payoffDef.payoffType);
    }
}

